func (r *mysqlResource) fetch(ctx context.Context, id string) (mysqlModel, diagnostics) {
	var diags diagnostics
	data, status, err := r.client.Do(ctx, http.MethodGet, fmt.Sprintf("/organisations/%s/mysql/%s", r.client.OrganisationID(), id), nil)
	if err != nil {
		if status == http.StatusNotFound {
			diags.AddError("not_found", "resource was deleted out-of-band")
			return mysqlModel{}, diags
		}
		diags.AddError("Fetch failed", err.Error())
		return mysqlModel{}, diags
	}
	var raw map[string]any
	if err := json.Unmarshal(data, &raw); err != nil {
		diags.AddError("Decode fetch response failed", err.Error())
		return mysqlModel{}, diags
	}
	return apiToMysqlModel(raw), diags
}

func (r *mysqlResource) fetchRaw(ctx context.Context, id string) (map[string]any, error) {
	data, _, err := r.client.Do(ctx, http.MethodGet, fmt.Sprintf("/organisations/%s/mysql/%s", r.client.OrganisationID(), id), nil)
	if err != nil {
		return nil, err
	}
	var raw map[string]any
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	return raw, nil
}

